# Surah Yunus (chapter 10) — part 9: ayat 81-90 (IDs 1445-1454)
SURAH = 10

ENTRIES = {
1445: (
"پس — جب — انہوں نے — پھینکا — موسیٰ نے — کہا — یہ — جو — تم — لائے — وہ — جادو ہے — بے شک — اللہ — اسے — باطل کر دے گا — بے شک — اللہ — فساد کرنے والوں — کا کام — درست نہیں کرتا",
"""۱۔ جادو — باطل — ہو جائے گا — اللہ — بول دیتا ہے۔
۲۔ ’’فَلَمَّا أَلْقَوْا قَالَ مُوسَىٰ مَا جِئْتُم بِهِ السِّحْرُ إِنَّ اللَّهَ سَيُبْطِلُهُ إِنَّ اللَّهَ لَا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ‘‘ — پس — جب — انہوں نے — پھینکا — موسیٰ نے — کہا — یہ — جو — تم — لائے — وہ — جادو ہے — بے شک — اللہ — اسے — باطل کر دے گا — بے شک — اللہ — فساد کرنے والوں — کا کام — درست نہیں کرتا — یعنی موسیٰؑ نے کہا — یہ — جو تم لائے — وہ — جادو ہے؛ اللہ — اسے باطل کر دے گا؛ وہ — مفسدوں — کا — کام — درست — نہیں کرتا۔
۳۔ عملی سبق: باطل — اپنے آپ ختم ہو جاتا ہے؛ اللہ — سچ — کو غالب کرتا ہے۔"""
),
1446: (
"اور — اللہ — حق — کو — اپنے کلمات — کے ساتھ — ثابت کرتا ہے — خواہ — مجرم — ناخوش ہوں",
"""۱۔ اللہ — حق — کو — اپنے کلمات — سے — ثابت کرتا ہے۔
۲۔ ’’وَيُحِقُّ اللَّهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ‘‘ — اور — اللہ — حق — کو — اپنے کلمات — کے ساتھ — ثابت کرتا ہے — خواہ — مجرم — ناخوش ہوں — یعنی اللہ — حق کو — اپنے کلمات کے ساتھ — سچ ثابت کرتا ہے — چاہے — مجرم — ناخوش ہوں۔
۳۔ عملی سبق: حق — آخر میں — غالب آتا ہے؛ صبر رکھیں۔"""
),
1447: (
"پس — موسیٰؑ — پر — ایمان — نہیں لائے — مگر — ان — کی — قوم — کی — تھوڑی سی نسل — فرعون اور اس کے سردار — کے — خوف سے — کہ وہ — انہیں — آزمائیں — اور — بے شک — فرعون — زمین میں — سرکش — تھا — اور — وہ — فضول خرچ کرنے والوں — میں — سے تھا",
"""۱۔ فرعون — کے — ظلم کے باوجود — تھوڑی نسل نے — ایمان لایا۔
۲۔ ’’فَمَا آمَنَ لِمُوسَىٰ إِلَّا ذُرِّيَّةٌ مِّن قَوْمِهِ عَلَىٰ خَوْفٍ مِّن فِرْعَوْنَ وَمَلَئِهِمْ أَن يَفْتِنَهُمْ وَإِنَّ فِرْعَوْنَ لَعَالٍ فِي الْأَرْضِ وَإِنَّهُ لَمِنَ الْمُسْرِفِينَ‘‘ — پس — موسیٰؑ — پر — ایمان — نہیں لائے — مگر — ان — کی — قوم — کی — تھوڑی سی نسل — فرعون اور اس کے سردار — کے — خوف سے — کہ وہ — انہیں — آزمائیں — اور — بے شک — فرعون — زمین میں — سرکش — تھا — اور — وہ — فضول خرچ کرنے والوں — میں — سے تھا — یعنی فرعون — کے خوف سے — بنی اسرائیل — کی تھوڑی سی نسل — ایمان لائی — مگر — فرعون — ظالم — اور — فضول خرچ — تھا۔
۳۔ عملی سبق: ظالم — کا — خوف — کبھی — ایمان کی راہ — نہ روکے۔"""
),
1448: (
"اور — موسیٰ — نے — کہا — اے میری قوم — اگر — تم — اللہ — پر ایمان لائے — ہو — تو — اسی پر — بھروسہ کرو — اگر — تم — مسلمان — ہو",
"""۱۔ موسیٰؑ — قوم کو توکل کی تعلیم دیتے ہیں۔
۲۔ ’’وَقَالَ مُوسَىٰ يَا قَوْمِ إِن كُنتُمْ آمَنتُم بِاللَّهِ فَعَلَيْهِ تَوَكَّلُوا إِن كُنتُم مُّسْلِمِينَ‘‘ — اور — موسیٰ — نے — کہا — اے میری قوم — اگر — تم — اللہ — پر ایمان لائے — ہو — تو — اسی پر — بھروسہ کرو — اگر — تم — مسلمان — ہو — یعنی موسیٰؑ — فرماتے ہیں — اگر تم اللہ پر ایمان لائے ہو — تو — اسی — پر بھروسہ کرو — اگر تم مسلمان — ہو۔
۳۔ عملی سبق: ایمان — توکل — کے بغیر ادھورا ہے۔"""
),
1449: (
"پس — انہوں نے کہا — ہم نے — اللہ — پر — بھروسہ کیا — اے — ہمارے رب — ہمیں — ظالموں — کے لیے — آزمائش — نہ بنا",
"""۱۔ بنی اسرائیل — اللہ پر توکل کرتے ہیں — اور دعا کرتے ہیں۔
۲۔ ’’فَقَالُوا عَلَى اللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَۃً لِّلْقَوْمِ الظَّالِمِينَ‘‘ — پس — انہوں نے کہا — ہم نے — اللہ — پر — بھروسہ کیا — اے — ہمارے رب — ہمیں — ظالموں — کے لیے — آزمائش — نہ بنا — یعنی انہوں نے کہا — ہم نے اللہ پر توکل کیا — اے رب ہمیں — ظالموں کے لیے آزمائش — نہ بنا۔
۳۔ عملی سبق: اللہ پر توکل — ہر آزمائش میں — کامیابی ہے۔"""
),
1450: (
"اور — ہمیں — اپنی رحمت — سے — کافر — قوم — سے — نجات دے",
"""۱۔ رحمتِ الٰہی — ظالموں سے — نجات کی دعا۔
۲۔ ’’وَنَجِّنَا بِرَحْمَتِكَ مِنَ الْقَوْمِ الْكَافِرِينَ‘‘ — اور — ہمیں — اپنی رحمت — سے — کافر — قوم — سے — نجات دے — یعنی اپنی رحمت سے — ہمیں — کافر قوم — سے نجات دے۔
۳۔ عملی سبق: دعا — رحمت کے — ساتھ — مانگو؛ وہی — قبول ہوتی ہے۔"""
),
1451: (
"اور — ہم — نے — موسیٰ اور ان کے بھائی — کو — وحی کی — کہ — اپنے — لیے — مصر میں — گھر — بنائیں — اور — اپنے — گھروں کو — قبلہ — بناؤ — اور — نماز — قائم کرو — اور — مؤمنوں کو — خوشخبری دو",
"""۱۔ موسیٰؑ اور ہارون — کو — مصر میں گھر بنانے کا حکم۔
۲۔ ’’وَأَوْحَيْنَا إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّآ لِقَوْمِكُمَا بِمِصْرَ بُيُوتًا وَاجْعَلُوا بُيُوتَكُمْ قِبْلَۃً وَأَقِيمُوا الصَّلَاۃَ وَبَشِّرِ الْمُؤْمِنِينَ‘‘ — اور — ہم — نے — موسیٰ اور ان کے بھائی — کو — وحی کی — کہ — اپنے — لیے — مصر میں — گھر — بنائیں — اور — اپنے — گھروں کو — قبلہ — بناؤ — اور — نماز — قائم کرو — اور — مؤمنوں کو — خوشخبری دو — یعنی موسیٰؑ اور ہارونؑ کو وحی ہوئی — مصر میں — گھر بنائیں — انہیں قبلہ بناؤ — اور — نماز قائم کرو — اور مؤمنوں کو خوشخبری دو۔
۳۔ عملی سبق: نماز قائم — کرو — اور — مؤمنوں کو — خوشخبری — دو۔"""
),
1452: (
"اور — موسیٰ — نے — کہا — اے ہمارے رب — تو نے — فرعون اور اس کے سرداروں — کو — دنیا کی زندگی میں — زینت اور مال — دیا — اے — ہمارے رب — تاکہ — وہ — تیری راہ — سے گمراہ کریں — اے — ہمارے رب — ان — کے مالوں کو — برباد کر دے — اور — ان — کے دلوں — کو — سخت کر دے — پس — وہ — ایمان — نہ لائیں — یہاں تک کہ — وہ — دردناک عذاب — دیکھ لیں",
"""۱۔ موسیٰؑ — کی فرعون کے خلاف دعا۔
۲۔ ’’وَقَالَ مُوسَىٰ رَبَّنَا إِنَّكَ آتَيْتَ فِرْعَوْنَ وَمَلَأَهُ زِينَۃً وَأَمْوَالًا فِي الْحَيَاۃِ الدُّنْيَا رَبَّنَا لِيُضِلُّوا عَن سَبِيلِكَ رَبَّنَا اطْمِسْ عَلَىٰ أَمْوَالِهِمْ وَاشْدُدْ عَلَىٰ قُلُوبِهِمْ فَلَا يُؤْمِنُوا حَتَّىٰ يَرَوُا الْعَذَابَ الْأَلِيمَ‘‘ — اور — موسیٰ — نے — کہا — اے ہمارے رب — تو نے — فرعون اور اس کے سرداروں — کو — دنیا کی زندگی میں — زینت اور مال — دیا — اے — ہمارے رب — تاکہ — وہ — تیری راہ — سے گمراہ کریں — اے — ہمارے رب — ان — کے مالوں کو — برباد کر دے — اور — ان — کے دلوں — کو — سخت کر دے — پس — وہ — ایمان — نہ لائیں — یہاں تک کہ — وہ — دردناک عذاب — دیکھ لیں — یعنی موسیٰؑ — نے دعا کی — فرعون کے مال — برباد کرو اور اس کے دل — سخت کرو — کہ وہ دردناک عذاب — تک ایمان — نہ لائیں۔
۳۔ عملی سبق: ظالم — کو — زینت اور مال — بدترین عاقبت — دے سکتے ہیں۔"""
),
1453: (
"فرمایا — تمہاری دونوں — کی دعا — قبول ہو گئی — پس — تم دونوں — جم — جاؤ — اور — ان — لوگوں — کے راستے — کی پیروی — نہ کرو — جو — نہیں جانتے",
"""۱۔ اللہ — موسیٰ اور ہارونؑ کی — دعا — قبول فرماتا ہے۔
۲۔ ’’قَالَ قَدْ أُجِيبَت دَّعْوَتُكُمَا فَاسْتَقِيمَا وَلَا تَتَّبِعَانِّ سَبِيلَ الَّذِينَ لَا يَعْلَمُونَ‘‘ — فرمایا — تمہاری دونوں — کی دعا — قبول ہو گئی — پس — تم دونوں — جم — جاؤ — اور — ان — لوگوں — کے راستے — کی پیروی — نہ کرو — جو — نہیں جانتے — یعنی اللہ نے کہا — تمہاری دونوں کی دعا — قبول ہو گئی؛ استقامت — اختیار کرو — لاعلمی — والوں کا راستہ — مت چلو۔
۳۔ عملی سبق: دعا — قبول ہو تو — استقامت — اختیار کرو۔"""
),
1454: (
"اور — ہم — نے — بنی اسرائیل کو — سمندر — سے — گزارا — پس — فرعون اور اس کے لشکر — ان — کے پیچھے — چلے — ظلم اور زیادتی کے طور پر — یہاں تک کہ — جب — اس — کو — ڈوبنا — آ لیا — تو — اس نے کہا — میں — ایمان لاتا ہوں — اس — پر کہ — اس کے سوا — کوئی معبود نہیں — جس — پر بنی اسرائیل — ایمان لائے — اور — میں — مسلمانوں میں سے — ہوں",
"""۱۔ فرعون — ڈوبنے کے وقت — ایمان کا دعویٰ کرتا ہے۔
۲۔ ’’وَجَاوَزْنَا بِبَنِي إِسْرَائِيلَ الْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُ بَغْيًا وَعَدْوًا حَتَّىٰ إِذَا أَدْرَكَهُ الْغَرَقُ قَالَ آمَنتُ أَنَّهُ لَا إِلَٰهَ إِلَّا الَّذِي آمَنَتْ بِهِ بَنُو إِسْرَائِيلَ وَأَنَا مِنَ الْمُسْلِمِينَ‘‘ — اور — ہم — نے — بنی اسرائیل کو — سمندر — سے — گزارا — پس — فرعون اور اس کے لشکر — ان — کے پیچھے — چلے — ظلم اور زیادتی کے طور پر — یہاں تک کہ — جب — اس — کو — ڈوبنا — آ لیا — تو — اس نے کہا — میں — ایمان لاتا ہوں — اس — پر کہ — اس کے سوا — کوئی معبود نہیں — جس — پر بنی اسرائیل — ایمان لائے — اور — میں — مسلمانوں میں سے — ہوں — یعنی بنی اسرائیل — سمندر — پار کیے؛ فرعون — پیچھے — دوڑا — جب ڈوبنے لگا تو ایمان کا دعویٰ کیا — مگر بہت دیر — ہو چکا تھا۔
۳۔ عملی سبق: عذاب کے وقت — ایمان — مقبول نہیں؛ پہلے ایمان — لاؤ۔"""
),
}
